test('lateFee with larger amount and many days', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = lateFee(issued, '2025-03-01');
  const dueDate = issued.dueDate;
  const asOf = '2025-03-01';
  const due = new Date(dueDate + 'T00:00:00Z');
  const asOfDate = new Date(asOf + 'T00:00:00Z');
  const msPerDay = 24 * 60 * 60 * 1000;
  const days = Math.floor((asOfDate.getTime() - due.getTime()) / msPerDay);
  const expected = Math.round(days * totals.total * 0.0004);
  assert.equal(r3, expected);
  assert.ok(r3 > 0);
});

